<template>
  <div class="overview-page">
    <section class="overview-hero">
      <div>
        <div class="hero-overline"><span class="pulse-dot"></span> LIVE DATA INTELLIGENCE</div>
        <h2>你好，RuTika。<br /><span>今天从哪里开始探索？</span></h2>
        <p>把数据库、业务知识和语义向量放在同一个视野里，找到值得回答的问题。</p>
      </div>
      <div class="hero-clock"><span>数据空间</span><strong>{{ currentTime }}</strong><small>最后同步 · {{ updateTime || '刚刚' }}</small></div>
    </section>

    <section class="stat-grid">
      <button v-for="stat in stats" :key="stat.key" class="stat-card" @click="navigate(stat.target)"><span class="stat-label">{{ stat.label }}</span><strong>{{ stat.value }}</strong><small>{{ stat.note }} <i>↗</i></small><span class="stat-spark" :class="stat.tone"><b v-for="(height, index) in stat.spark" :key="index" :style="{ height: `${height}px` }"></b></span></button>
    </section>

    <section class="command-card">
      <div class="command-copy"><div class="eyebrow">ASK YOUR DATA</div><h3>用一句话，打开一个数据视野</h3><p>Oripio 会理解你的问题、定位相关数据，并把分析过程完整展示出来。</p></div>
      <div class="command-input"><span>⌕</span><input v-model="question" placeholder="例如：最近一周各工序的良率趋势如何？" @keyup.enter="ask" /><button @click="ask">开始分析 <span>↗</span></button></div>
      <div class="suggestions"><button v-for="item in suggestions" :key="item" @click="question = item">{{ item }} <span>＋</span></button></div>
    </section>

    <VectorSpace />

    <section class="lower-grid">
      <div class="signal-card"><div class="section-heading"><div><div class="eyebrow">BUSINESS SIGNALS</div><h3>近期值得关注</h3></div><button @click="loadAttention">刷新 ↻</button></div><div v-if="attentionLoading" class="empty-state">正在读取业务信号…</div><div v-else-if="attentionPoints.length" class="signal-list"><div v-for="point in attentionPoints.slice(0, 3)" :key="point.id" class="signal-item"><span class="signal-icon">{{ point.icon || '·' }}</span><div><strong>{{ point.title }}</strong><p>{{ point.detail }}</p></div><span class="signal-arrow">→</span></div></div><div v-else class="empty-state">连接数据库后，这里会显示自动发现的业务关注点。</div></div>
      <div class="quick-card"><div class="section-heading"><div><div class="eyebrow">WORKSPACES</div><h3>进入数据空间</h3></div></div><button class="quick-link" @click="navigate('data')"><span class="quick-icon cyan">◈</span><div><strong>数据资源</strong><small>浏览表结构和字段</small></div><b>→</b></button><button class="quick-link" @click="navigate('knowledge')"><span class="quick-icon purple">✦</span><div><strong>业务知识</strong><small>查看指标与关系图谱</small></div><b>→</b></button><button class="quick-link" @click="navigate('ask')"><span class="quick-icon orange">⌁</span><div><strong>智能问析</strong><small>继续你的数据对话</small></div><b>→</b></button></div>
    </section>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import VectorSpace from '../components/VectorSpace.vue'

const emit = defineEmits<{ (event: 'navigate', page: string): void; (event: 'navigate-knowledge', scene: string): void }>()
const overview = ref<Record<string, number>>({})
const attentionPoints = ref<any[]>([])
const attentionLoading = ref(false)
const question = ref('')
const now = ref(new Date())
let timer: number | undefined
const currentTime = computed(() => now.value.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }))
const updateTime = ref('')
const suggestions = ['分析各工序良率', '最近设备停机记录', '库存预警产品清单']
const stats = computed(() => [
  { key: 'tables', label: '数据表', value: overview.value.table_count ?? '—', note: '可探索的数据源', target: 'data', tone: 'cyan', spark: [11, 20, 15, 27, 18, 32, 24] },
  { key: 'columns', label: '语义字段', value: overview.value.total_columns ?? '—', note: '已建立字段上下文', target: 'knowledge', tone: 'purple', spark: [18, 13, 25, 19, 30, 24, 35] },
  { key: 'relations', label: '数据关系', value: overview.value.relationship_count ?? '—', note: '可追踪的关联', target: 'knowledge', tone: 'orange', spark: [12, 25, 18, 22, 29, 20, 30] },
  { key: 'topics', label: '分析主题', value: overview.value.topic_count ?? '—', note: '可直接进入的场景', target: 'knowledge', tone: 'green', spark: [22, 17, 28, 20, 32, 27, 36] },
])
function navigate(page: string) { emit('navigate', page) }
function ask() { if (question.value.trim()) { localStorage.setItem('oripio_pending_question', question.value.trim()); navigate('ask') } }
async function loadOverview() { try { const response = await fetch('/api/tables/overview'); if (!response.ok) return; const data = await response.json(); overview.value = data.data || {}; updateTime.value = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) } catch { /* 页面保持可浏览 */ } }
async function loadAttention() { attentionLoading.value = true; try { const response = await fetch('/api/tables/attention-points'); if (!response.ok) return; const data = await response.json(); attentionPoints.value = data.points || [] } catch { attentionPoints.value = [] } finally { attentionLoading.value = false } }
onMounted(() => { loadOverview(); loadAttention(); timer = window.setInterval(() => { now.value = new Date() }, 30000) })
onUnmounted(() => { if (timer) window.clearInterval(timer) })
</script>

<style scoped>
