px; border-radius: 3px; background: #8adbcf; opacity: .78; }.stat-spark.purple b { background: #a8a0f0; }.stat-spark.orange b { background: #f0bd84; }.stat-spark.green b { background: #88d7a7; }.command-card { padding: 27px 29px 23px; border: 1px solid #d5e2ea; border-radius: 22px; background: linear-gradient(120deg, #eef9f7, #f7fbff 60%, #f1efff); box-shadow: 0 13px 34px rgba(46,86,106,.06); }.command-copy h3, .section-heading h3 { margin-top: 7px; color: #20344a; font-size: 20px; letter-spacing: -.04em; }.command-copy p { margin-top: 6px; color: #8291a1; font-size: 11px; }.command-input { display: flex; align-items: center; gap: 10px; margin-top: 21px; padding: 6px 7px 6px 14px; border: 1px solid #d5e1e8; border-radius: 13px; background: rgba(255,255,255,.9); }.command-input > span { color: #44ad9c; font-size: 22px; }.command-input input { min-width: 0; flex: 1; border: 0; outline: none; color: #344b60; background: transparent; font-size: 12px; }.command-input button { padding: 10px 14px; border: 0; border-radius: 9px; color: white; background: #20364e; font-size: 11px; font-weight: 750; cursor: pointer; }.command-input button span { margin-left: 12px; color: #91efdd; font-size: 15px; }.suggestions { display: flex; gap: 7px; margin-top: 12px; flex-wrap: wrap; }.suggestions button { padding: 7px 10px; border: 1px solid #d8e4ea; border-radius: 8px; color: #728396; background: rgba(255,255,255,.5); font-size: 10px; cursor: pointer; }.suggestions button:hover { border-color: #9bd8cf; color: #238e80; }.suggestions span { margin-left: 5px; color: #9bb7ba; }.lower-grid { display: grid; grid-template-columns: 1.45fr 1fr; gap: 18px; }.signal-card, .quick-card { padding: 23px; border: 1px solid #e1e8ee; border-radius: 19px; background: rgba(255,255,255,.7); }.section-heading { display: flex; align-items: flex-start; justify-content: space-between; }.section-heading h3 { margin-bottom: 17px; font-size: 17px; }.section-heading button { border: 0; color: #91a0ad; background: transparent; font-size: 10px; cursor: pointer; }.signal-list { display: flex; flex-direction: column; gap: 9px; }.signal-item { display: flex; align-items: center; gap: 12px; padding: 11px 12px; border: 1px solid #edf1f4; border-radius: 11px; }.signal-icon { display: grid; width: 28px; height: 28px; place-items: center; border-radius: 8px; color: #bf7250; background: #fff0e6; }.signal-item strong { display: block; color: #43566a; font-size: 11px; }.signal-item p { margin-top: 4px; color: #9aa7b4; font-size: 10px; }.signal-arrow { margin-left: auto; color: #9baab7; }.empty-state { padding: 27px 0; color: #9aa8b5; font-size: 11px; text-align: center; }.quick-card { display: flex; flex-direction: column; }.quick-link { display: flex; align-items: center; gap: 11px; padding: 11px 2px; border: 0; border-top: 1px solid #edf1f4; background: transparent; text-align: left; cursor: pointer; }.quick-link:hover strong { color: #138879; }.quick-icon { display: grid; width: 31px; height: 31px; place-items: center; border-radius: 9px; font-size: 15px; }.quick-icon.cyan { color: #158d82; background: #e2f8f3; }.quick-icon.purple { color: #7164ca; background: #eeeaff; }.quick-icon.orange { color: #b77435; background: #fff0dc; }.quick-link div { flex: 1; }.quick-link strong, .quick-link small { display: block; }.quick-link strong { color: #465a6f; font-size: 11px; }.quick-link small { margin-top: 3px; color: #9ca9b5; font-size: 9px; }.quick-link b { color: #b2bdc6; font-size: 14px; font-weight: 400; }.quick-link:hover b { color: #1a9a89; }
@media (max-width: 900px) { .stat-grid { grid-template-columns: repeat(2, 1fr); }.lower-grid { grid-template-columns: 1fr; } }
@media (max-width: 560px) { .overview-hero { align-items: flex-start; flex-direction: column; }.hero-clock { padding: 0; border: 0; }.stat-grid { grid-template-columns: 1fr 1fr; }.stat-card { min-height: 112px; }.stat-spark { display: none; }.command-input { align-items: stretch; flex-wrap: wrap; }.command-input input { min-width: 150px; }.command-input button { width: 100%; } }
</style>
